 logline:'보도 위의 공유 킥보드, 부딪힌 사람과 떠난 사람.',
 summary:'저녁 퇴근길 보도에서 공유 킥보드가 보행자 {B|와} 부딪혔다. {B|은} 손목이 부러졌고, 킥보드 이용자는 그대로 떠났다. 대여 기록에 따라 대학생 {A|이} 도주치상 혐의로 기소됐다. {A|은} 그 시간에 킥보드를 빌린 건 맞지만 친구에게 넘겨줬다고 말한다.',
