  {role:'명품 감정사',story:'위탁 가방의 진품 여부를 감정했다. 흠집의 위치까지 기록해 두는 습관이 있다.',says:'제 감정 기록에는 손잡이 왼쪽 흠집이 적혀 있습니다',stake:'감정 기록의 정확성을 지켜야 한다'}
