  {role:'피고의 전 부하 직원',story:'{B} 밑에서 10년을 일했다. 지금도 원고 회사에 다닌다.',says:'상무님은 설계를 머리로 다 기억하는 분이에요. 파일이 필요 없는 사람입니다',stake:'회사와 옛 상사 사이에 끼어 있다'},
  {role:'경쟁사 개발 책임자',story:'{B|를} 영입한 사람. 신제품 개발은 영입 전부터 진행 중이었다고 말한다.',says:'그 제품은 영입 1년 전부터 개발하던 겁니다. 설계 문서도 그대로 있습니다',stake:'자기 회사의 제품이 도용으로 몰리는 것을 막아야 한다'}
