  {title:'회사 앞 방범 카메라',shows:'비슷한 체격의 사람이 두 번 서성였다',caveat:'우산에 얼굴이 가려 있다',flaw:'source'},
  {title:'휴대전화 위치 기록',shows:'새 집 근처에서 {A}의 신호가 잡혔다',caveat:'통신사에 요청한 기간보다 넓은 범위가 제출됐다',flaw:'illegal'}
