/* Courtroom detail for curated cases, part 1 (homicide 5).
 * charge: statute and legal sentence range in years (life = 무기징역 allowed, fine = upper limit in 만 원, 0 = no fine).
 * demand: the prosecution's sentencing request in years.
 * issues: what the trial must decide. evidence[i]/witnesses[i] line up with the case's base lists.
 * evidence: kind, by (who submitted), when, excerpt (original text), how (how it was obtained), issue, side (p = for the
 *   charge, d = raises doubt, n = neutral), check (what to compare it with).
 * witnesses: lead (a leading question someone may object to), q (questions the judge can ask; a = answer, or
 *   {did,didnt,reason} answers by hidden truth; hidden = opens only through `next`).
 * late: evidence one side can add between trial days, with the other side's answer (rebut).
 * rebut: the prosecution's answer to the defence. closing: final argument.
 */
